(()=>{
const C=Commission,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let p=C.project(),s=C.fresh(),selected='P1',clock=null,editor;const pulses={};
try{const saved=JSON.parse(localStorage.getItem('plcquest.master.v1')||'null');if(saved){const candidate=C.project();for(const id of C.deviceIds){candidate.devices[id].ip=String(saved.devices?.[id]?.ip||'');candidate.devices[id].connected=saved.devices?.[id]?.connected!==false;}for(const id of C.ids){const old=saved.controllers?.[id];if(!old)continue;const c=candidate.controllers[id];c.io=String(old.io||'');c.drive=String(old.drive||'');for(const peer of C.peers[id])c.peers[peer]=String(old.peers?.[peer]||'');for(const k of ['inputs','outputs'])c[k]=Array.from({length:8},(_,i)=>(k==='inputs'?C.ins[id]:C.outs[id]).includes(old[k]?.[i])?old[k][i]:'');c.driveMode=old.driveMode==='NETWORK'?'NETWORK':'LOCAL';c.hz=Number(old.hz)||0;c.mode='PROGRAM';try{C.validate(old.downloaded,id);c.downloaded=old.downloaded;}catch{}if(Array.isArray(old.draft)&&old.draft.length<=80&&old.draft.every(r=>Array.isArray(r.groups)&&r.groups.length>0&&r.groups.length<=10&&r.groups.every(g=>Array.isArray(g)&&g.length>0&&g.length<=4&&g.every(t=>typeof t==='string'))&&['OTE','OTL','OTU','TON','RTO','CTU','RES'].includes(r.type))){c.draft=old.draft;}}candidate.hmi={...candidate.hmi,...saved.hmi};p=candidate;}}
catch{}
function save(){try{localStorage.setItem('plcquest.master.v1',JSON.stringify(p));$('saveStatus').textContent='Project saved in this browser. Reloading keeps your project and returns controllers to PROGRAM mode.';}catch{$('saveStatus').textContent='Browser storage unavailable. Your project lasts while this tab stays open.';}}
function stopClock(){clearInterval(clock);clock=null;$('scanRun').textContent='Start scans';}
function reset(){stopClock();s=C.fresh();for(const key of ['estop','driveTrip','blocked'])$(key).checked=false;for(const key of Object.keys(pulses))delete pulses[key];render();}
function configChange(){stopClock();s=C.fresh();for(const key of ['estop','driveTrip','blocked'])$(key).checked=false;save();render();$('testResults').textContent='Configuration changed. Run acceptance tests again.';}
const opt=(list,value)=>['',...list].map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x||'Unassigned')}</option>`).join('');
function forms(){
$('devices').innerHTML=C.deviceIds.map(id=>`<div class="device-card"><h3>${id}</h3><label>IPv4 address<input type="text" data-device="${id}" value="${esc(p.devices[id].ip)}" placeholder="10.20.30.10" inputmode="decimal"></label><label><input type="checkbox" data-cable="${id}" ${p.devices[id].connected?'checked':''}> Cable connected</label><span class="live-device" id="device-${id}"></span></div>`).join('');
$('connections').innerHTML=C.ids.map((id,i)=>{const c=p.controllers[id];return `<div class="device-card"><h3>${id}</h3><label>IO${i+1} address<input type="text" data-plc="${id}" data-property="io" value="${esc(c.io)}"></label><label>VFD${i+1} address<input type="text" data-plc="${id}" data-property="drive" value="${esc(c.drive)}"></label>${C.peers[id].map(peer=>`<label>${peer} peer address<input type="text" data-plc="${id}" data-peer="${peer}" value="${esc(c.peers[peer])}"></label>`).join('')}<span id="health-${id}"></span></div>`;}).join('');
$('ioPanels').innerHTML=C.ids.map((id,i)=>{const c=p.controllers[id];return `<div class="device-card"><h3>${id} / IO${i+1}</h3><div class="io-map">${['inputs','outputs'].map(k=>Array.from({length:8},(_,j)=>`<label>${k==='inputs'?'I':'O'}${j}<select data-map="${k}" data-plc="${id}" data-channel="${j}">${opt(k==='inputs'?C.ins[id]:C.outs[id],c[k][j])}</select></label>`).join('')).join('')}</div><h3>VFD${i+1}</h3><label>Command source<select data-plc="${id}" data-property="driveMode"><option ${c.driveMode==='LOCAL'?'selected':''}>LOCAL</option><option ${c.driveMode==='NETWORK'?'selected':''}>NETWORK</option></select></label><label>Reference Hz<input type="number" min="0" max="60" step="1" data-plc="${id}" data-property="hz" value="${c.hz}"></label></div>`;}).join('');
$('hmiBindings').innerHTML=`<div class="device-card"><label>P1 target address<input type="text" data-hmi="target" value="${esc(p.hmi.target)}"></label>${['start','stop','reset'].map(k=>`<label>${k.toUpperCase()} binding<select data-hmi="${k}">${opt(['HMI_START','HMI_STOP','HMI_RESET'],p.hmi[k])}</select></label>`).join('')}</div><div class="device-card">${['running','alarm'].map(k=>`<label>${k.toUpperCase()} lamp<select data-hmi="${k}">${opt(C.targets(),p.hmi[k])}</select></label>`).join('')}<p class="note">Indicators read your P1 program. Program the selected tags to reflect actual running and alarm conditions.</p></div>`;
}
function controller(){const c=p.controllers[selected];const conf={rows:c.draft,tags:C.tags(selected),outputs:C.targets(),limit:80,onChange:rows=>{c.draft=rows;save();downloadState();$('testResults').textContent='Draft changed. Download and rerun acceptance tests.';}};if(editor)editor.setData(conf);else editor=new RailEditor($('masterLadder'),conf);$('plcMode').value=c.mode;$('download').textContent='Download to '+selected;downloadState();}
function downloadState(){const c=p.controllers[selected];$('downloadStatus').textContent=JSON.stringify(c.draft)===JSON.stringify(c.downloaded)?(c.downloaded.length?'Downloaded program matches draft.':'No program downloaded.'):'Draft differs from downloaded program.';}
const coords={A:[100,110],B:[300,110],C:[510,110],D:[710,110],E:[920,110],F:[920,295]};
function floor(){let out='';const names={A:'Infeed',B:'Stop gate',C:'Lift',D:'Inspection buffer',E:'Sorter',F:'Dispatch'};for(const [i,id]of ['A','B','C','D','E','F'].entries()){const [x,y]=coords[id],cell=s.cells[id],next=coords['ABCDEF'[i+1]],on=s.cmd['MOTOR_'+id];if(next)out+=`<path d="M${x} ${y}L${next[0]} ${next[1]}" stroke="#899376" stroke-width="24"/><path d="M${x} ${y}L${next[0]} ${next[1]}" stroke="#ddd2b3" stroke-width="2" stroke-dasharray="5 12"/>`;out+=`<g transform="translate(${x},${y})"><rect x="-57" y="-31" width="114" height="62" rx="8" fill="${on?'#788863':'#434d43'}" stroke="#bbc3a7" stroke-width="2"/><text y="-45" text-anchor="middle" fill="#eee3cf" font-size="16">${id} · ${names[id]}</text><text y="53" text-anchor="middle" fill="#c8d0b4" font-size="13">S ${cell.box?1:0} · Q ${on?1:0}</text>${id==='C'?`<text y="76" text-anchor="middle" fill="#e5b881" font-size="13">Lift ${Math.round(cell.position*100)}%</text>`:''}</g>`;}
 out+=`<path d="M920 110L1050 220" stroke="#b5886b" stroke-width="16"/><text x="1030" y="250" fill="#eac495" text-anchor="middle">REJECT ${s.reject}</text>`;
 for(const [id,cell]of Object.entries(s.cells)){if(!cell.box)continue;const [x,y]=coords[id],next=coords['ABCDEF'['ABCDEF'.indexOf(id)+1]],free=next&&!s.cells['ABCDEF'['ABCDEF'.indexOf(id)+1]].box,progress=free?Math.min(.85,cell.elapsed/.7):0,px=x+(next?next[0]-x:0)*progress,py=y+(next?next[1]-y:0)*progress;out+=`<g transform="translate(${px},${py})"><rect x="-17" y="-17" width="34" height="34" rx="3" fill="${cell.box.bad?'#d7896c':'#e7c68c'}" stroke="#24322a"/><text y="5" text-anchor="middle" fill="#24322a" font-weight="bold">${cell.box.id}</text></g>`;}
 for(const [i,id]of C.ids.entries()){out+=`<rect x="${40+i*300}" y="270" width="230" height="95" rx="8" fill="#28332d" stroke="${C.health(p,id)?'#acc28e':'#c87f66'}"/><text x="${155+i*300}" y="299" text-anchor="middle" fill="#f0dfb8">${id} · ${p.controllers[id].mode}</text><text x="${155+i*300}" y="325" text-anchor="middle" fill="#c7ceb4">REQ ${s.bus[id].TX_REQUEST?1:0} READY ${s.bus[id].TX_READY?1:0} ACK ${s.bus[id].TX_ACK?1:0}</text><text x="${155+i*300}" y="347" text-anchor="middle" fill="#c7ceb4">RUN ${s.bus[id].TX_RUN?1:0} ALARM ${s.bus[id].TX_ALARM?1:0}</text>`;}
 return out;
}
function render(){$('masterDiagram').innerHTML=floor();$('plantStats').textContent=`Time ${s.t.toFixed(1)} s · Fed ${s.fed}/12 · Good ${s.good}/8 · Reject ${s.reject}/4 · Incorrect ${s.wrong} · Packets ${s.packets}`;$('lineStatus').textContent=s.protocolErrors.at(-1)||'Use Start scans, then the configured HMI Start button. All controllers must be downloaded and in RUN.';for(const id of C.ids){const ok=C.health(p,id);$('health-'+id).textContent=ok?'Connections healthy':'Connection / drive not ready';$('health-'+id).className=ok?'online':'offline';}
 for(const id of C.deviceIds)$('device-'+id).textContent=p.devices[id].connected?(p.devices[id].ip?'Cable connected · '+p.devices[id].ip:'No address assigned'):'Cable disconnected';
 $('networkMonitor').textContent=C.ids.map(id=>C.peers[id].map(peer=>`${id} ← ${peer}: ${C.link(p,id,peer,p.controllers[id].peers[peer])?'LINK UP':'LINK DOWN'} | stale ${(s.rxAge[id+'_'+peer]||0).toFixed(1)} s | ${C.tx.map(t=>t.slice(3)+'='+Number(!!s.plc[id].bits['RX_'+peer+'_'+t.slice(3)])).join(' ')}`).join('\n')).join('\n');
 $('runningLamp').classList.toggle('on',C.lamp(p,s,'running'));$('alarmLamp').classList.toggle('on',C.lamp(p,s,'alarm'));$('alarmLamp').classList.add('alarm');$('hmiStatus').textContent=C.link(p,'HMI','P1',p.hmi.target)?'HMI connected to P1':'HMI OFFLINE';const match=JSON.stringify(p.controllers[selected].draft)===JSON.stringify(p.controllers[selected].downloaded);editor?.live(match?s.plc[selected].trace:[]);$('tagMonitor').textContent=Object.entries(s.plc[selected].bits).map(([k,v])=>k+' = '+Number(!!v)).join('  |  ');}
function step(){C.tick(p,s);for(const k of Object.keys(pulses)){pulses[k]--;if(pulses[k]<=0){C.hmi(p,s,k,false);delete pulses[k];}}render();}
$('scanRun').onclick=()=>{if(clock){stopClock();return;}clock=setInterval(step,100);$('scanRun').textContent='Pause scans';};$('scanStep').onclick=()=>{stopClock();step();};$('coldReset').onclick=reset;
$('controller').onchange=()=>{selected=$('controller').value;controller();render();};
$('download').onclick=()=>{const c=p.controllers[selected];try{C.validate(c.draft,selected);if(!c.draft.length)throw Error('Add at least one rung.');stopClock();c.mode='PROGRAM';c.downloaded=C.clone(c.draft);s=C.fresh();save();controller();render();$('plcMessage').textContent='Downloaded to '+selected+'. Switch it to RUN, then start scans.';}catch(e){$('plcMessage').textContent=e.message;}};
$('plcMode').onchange=()=>{const c=p.controllers[selected];if($('plcMode').value==='RUN'&&!c.downloaded.length){$('plcMode').value='PROGRAM';$('plcMessage').textContent='Download a program first.';return;}c.mode=$('plcMode').value;configChange();};
for(const container of ['devices','connections','ioPanels','hmiBindings'])$(container).onchange=e=>{const el=e.target,d=el.dataset;if(d.device)p.devices[d.device].ip=el.value.trim();else if(d.cable){p.devices[d.cable].connected=el.checked;save();render();return;}else if(d.hmi)p.hmi[d.hmi]=el.value;else if(d.plc){const c=p.controllers[d.plc];if(d.peer)c.peers[d.peer]=el.value.trim();else if(d.map)c[d.map][Number(d.channel)]=el.value;else c[d.property]=d.property==='hz'?Math.max(0,Math.min(60,Number(el.value)||0)):el.value.trim();}configChange();};
for(const [id,action]of [['hmiStart','start'],['hmiStop','stop'],['hmiReset','reset']])$(id).onclick=()=>{if(C.hmi(p,s,action,true)){pulses[action]=3;$('hmiStatus').textContent=action.toUpperCase()+' pulse queued for 3 scans.';}else $('hmiStatus').textContent='Command not delivered. Check HMI connection and binding.';};
for(const key of ['estop','driveTrip','blocked'])$(key).onchange=()=>{s[key]=$(key).checked;render();};
$('audit').onclick=()=>{const issues=C.configIssues(p);$('auditResult').textContent=issues.length?issues.join('\n'):'Configuration audit passed. Proceed to acceptance tests.';};
$('test').onclick=()=>{stopClock();let result;try{result=C.acceptance(p);}catch(e){result={ok:false,results:[{name:'Program validation',ok:false,message:e.message}]};}$('testResults').innerHTML=`<h3>${result.ok?'Commissioning accepted':'Commissioning incomplete'}</h3>`+result.results.map(r=>`<div class="test-result ${r.ok?'pass':'fail'}"><strong>${r.ok?'PASS':'FAIL'} · ${esc(r.name)}</strong><p>${esc(r.message)}</p></div>`).join('');if(result.ok){try{localStorage.setItem('plcquest.master.passed.v1',new Date().toISOString());}catch{}}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopClock();});forms();controller();render();save();
})();
